import axios from 'axios'
import * as cheerio from 'cheerio'

export default {
  async discovery({ category, page = 1 }) {
    const url = 'https://91quanji.com'
    const { data } = await axios.get(url, {
      headers: { 'User-Agent': ua }
    })
    const $ = cheerio.load(data)
    const items = $('#list_videos_videos_index .thumb--videos, .thumb--videos').map((i, el) => {
      const href = $(el).find('a').attr('href') || ''
      return {
        key: href.startsWith('http') ? href : 'https://91quanji.com' + (href.startsWith('/') ? '' : '/') + href,
        title: $(el).find('.thumb-spot__title').text().trim() || `精选视频 ${i + 1}`,
        cover: $(el).find('.thumb__img img').attr('src') || $(el).find('img').attr('src'),
        badge: '高清',
        desc: '视频速览'
      }
    }).toArray().filter(it => it.cover)

    return {
      categories: ['精选推荐', '热门排行'],
      items,
      hasMore: true
    }
  },

  async detail({ key, item }) {
    const targetUrl = key.startsWith('http') ? key : 'https://91quanji.com/' + key
    const { data } = await axios.get(targetUrl, {
      headers: { 'User-Agent': ua }
    })
    const $ = cheerio.load(data)

    function I(r) {
      let n = ''
      for (let i = 0; i < r.length; ++i)
        n += String.fromCharCode(128 ^ r.charCodeAt(i))
      return n
    }

    let videoUrl = ''
    const scriptContent = $('script[type="text/javascript"]').text()
    const match = scriptContent.match(/eval\(([\s\S]*?)\)/)
    if (match) {
      let evalStr = match[1]
      evalStr = evalStr.substring(3, evalStr.length - 3)
      let scriptStr = I(evalStr)
      videoUrl = scriptStr.match(/url:\s*['"]([^'"]+)['"]/)?.[1] || ''
    }

    const recommendations = $('.thumb--videos').map((i, el) => {
      const href = $(el).find('a').attr('href') || ''
      return {
        key: href.startsWith('http') ? href : 'https://91quanji.com' + (href.startsWith('/') ? '' : '/') + href,
        title: $(el).find('.thumb-spot__title').text().trim() || `相关视频 ${i + 1}`,
        cover: $(el).find('.thumb__img img').attr('src') || $(el).find('img').attr('src'),
        badge: '推荐'
      }
    }).toArray().filter(r => r.key !== targetUrl)

    return {
      title: item?.title || '视频播放',
      cover: item?.cover,
      desc: '高清流畅播放源，支持分段与多清晰度。',
      tags: ['精选视频', '高清'],
      playUrl: videoUrl,
      recommendations
    }
  }
}

