      const href = $(el).find('a').attr('href') || ''
      return {
        key: href.startsWith('http') ? href : 'https://www.bqgka.com' + href,
        title: $(el).find('dl dt a, .title').text().trim() || `小说 ${i + 1}`,
        cover: $(el).find('.image img').attr('src'),
        badge: '连载',
        desc: $(el).find('dl dd').text().trim() || $(el).find('.author').text().trim()
      }
    }).toArray().filter(it => it.title)

    return {
      categories: ['热门推荐', '玄幻奇幻', '武侠修真', '都市言情'],
      items,
      hasMore: true
    }
  },

  async search({ keyword, page = 1 }) {
    const url = `https://www.bqgka.com/s?q=${encodeURIComponent(keyword)}`
    const { data } = await axios.get(url, {
      headers: { 'User-Agent': ua }
    })
    const $ = cheerio.load(data)
    const items = $('.so_list .bookbox, .bookbox').map((i, el) => {
      const href = $(el).find('.bookname a').attr('href') || ''
      return {
        key: href.startsWith('http') ? href : 'https://www.bqgka.com' + href,
        title: $(el).find('.bookname a').text().trim(),
        cover: $(el).find('.bookimg img').attr('src'),
        badge: $(el).find('.cat').text().trim() || '小说',
        desc: $(el).find('.author').text().trim() || $(el).find('.intro').text().trim()
      }
    }).toArray()

    return { items, hasMore: false }
  },

  async detail({ key, item }) {
    const targetUrl = key.startsWith('http') ? key : 'https://www.bqgka.com' + key
    const { data } = await axios.get(targetUrl, {
      headers: { 'User-Agent': ua }
    })
    const $ = cheerio.load(data)

    const title = $('.info h1').text().trim() || item?.title || '小说详情'
    const cover = $('.cover img').attr('src') || item?.cover
    const author = $('.small span').first().text().replace('作者：', '').trim()
    const desc = $('.intro').text().trim() || '暂无简介'

    const chapters = $('.listmain dd a').map((i, el) => {
      const href = $(el).attr('href') || ''
      return {
        key: href.startsWith('http') ? href : 'https://www.bqgka.com' + href,
        title: $(el).text().trim()
      }
    }).toArray().filter(ch => ch.key && ch.title && !ch.title.includes('最新章节'))

    return {
      title,
      cover,
      desc,
      author,
      tags: ['网文', '完结', '连载'],
      groups: [
        {
          name: '正文章节',
          items: chapters
        }
      ]
    }
  },

  async parse({ key }) {
    const targetUrl = key.startsWith('http') ? key : 'https://www.bqgka.com' + key
    const { data } = await axios.get(targetUrl, {
      headers: { 'User-Agent': ua }
    })
    const $ = cheerio.load(data)

    $('#chaptercontent script, #chaptercontent style').remove()
    let content = $('#chaptercontent').text().trim()
    content = content.replace(/\s{4}/g, '\n\n')

    return {
      type: 'novel',
      content
    }
  }
}
